package net.succ.solar_punk.damage;

import net.minecraft.core.registries.Registries;
import net.minecraft.data.worldgen.BootstrapContext;
import net.minecraft.resources.ResourceKey;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.damagesource.DamageType;
import net.minecraft.world.level.Level;
import net.succ.solar_punk.SolarPunk;

// Damage types are datapack registry entries, generated by ModWorldGenProvider.
public class ModDamageTypes {

    /** An erupting Geyser Vent. */
    public static final ResourceKey<DamageType> SCALDING = ResourceKey.create(Registries.DAMAGE_TYPE,
            ResourceLocation.fromNamespaceAndPath(SolarPunk.MODID, "scalding"));

    public static void bootstrap(BootstrapContext<DamageType> context) {
        // msgId gives the death message key: death.attack.solarpunk.scalding
        context.register(SCALDING, new DamageType(SolarPunk.MODID + ".scalding", 0.1f));
    }

    public static DamageSource source(Level level, ResourceKey<DamageType> type) {
        return level.damageSources().source(type);
    }
}
